@pragma('vm:entry-point')
int countShiftedTimetableMinutes(int plannedMask, int delayedMask) {
  int x = plannedMask ^ (((delayedMask << 1) | (delayedMask >> 59)) & ((1 << 60) - 1));
  int c = 0;
  while (x != 0) {
    c++;
    x &= x - 1;
  }
  return c;
}

@pragma('vm:entry-point')
void main() {
  assert(countShiftedTimetableMinutes(0, 0) == 0);
  assert(countShiftedTimetableMinutes(1, 1 << 59) == 0);
  assert(countShiftedTimetableMinutes(15, 3) == 2);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = countShiftedTimetableMinutes;

  expect(candidate(0, 0), 0);
  expect(candidate(1, 0), 1);
  expect(candidate(1, 1 << 59), 0);
  expect(candidate(0, 1 << 59), 1);
  expect(candidate(10, 5), 0);
  expect(candidate(15, 3), 2);
  expect(candidate((1 << 60) - 1, 0), 60);
  expect(candidate((1 << 60) - 1, (1 << 60) - 1), 0);
  expect(candidate((1 << 58) | 1, (1 << 57) | (1 << 59)), 0);
  expect(candidate(9, 12), 2);
}

