List<int> sortSpellcheckEdits(List<List<int>> corrections) {
  var indices = List.generate(corrections.length, (i) => i);
  indices.sort((a, b) {
    int dA = corrections[a][1], dB = corrections[b][1];
    return dA != dB ? dA - dB : corrections[b][0] - corrections[a][0];
