int flippedMorseDashCount(int symbol) {
  int masked = symbol & 0x1F;
  int flipped = (~masked) & 0x1F;
  int count = 0;
  while (flipped != 0) {
    count += flipped & 1;
    flipped >>= 1;
  }
  return count;
}

