List<int> roundPathDistancesToNearest5(List<List<int>> paths) => paths.map((path) {
  int d = 0;
  for (int i = 0; i < path.length - 2; i += 2) d += (path[i] - path[i+2]).abs() + (path[i+1] - path[i+3]).abs();
  return (d + 2) ~/ 5 * 5;
}).toList();

