List<double> tallyDiscrepancies(List<List<int>> precincts) {
  return precincts.map((row) {
    if (row.isEmpty) return 0.0;
    int checksum = row.last;
    int actual = row.sublist(0, row.length - 1).fold(0, (a, b) => a + b);
    return (checksum - actual).toDouble();
  }).toList();
}

@pragma('vm:entry-point')
