List<String> sortInventoryByRarity(List<String> inventory) {
  return List<String>.from(inventory)..sort((a, b) {
    int rarityA = int.parse(a.split(':')[1]);
    int rarityB = int.parse(b.split(':')[1]);
    int cmp = rarityB.compareTo(rarityA);
    if (cmp != 0) return cmp;
    return a.split(':')[0].compareTo(b.split(':')[0]);
  });
}

