List<int> categorizeWifiSignals(List<int> signals) {
  var bins = <int>[];
  for (var s in signals) {
    int quality = (s >> 3) & 0xF, rot = s & 0x3;
    int rotated = ((quality << rot) | (quality >> (4 - rot))) & 0xF, bin = (rotated >> 2) & 0x3;
    bins.add(bin);
  }
  return bins;
}

