@pragma('vm:entry-point')
String batteryCycleDriftMap(List<int> levels) {
  String scan(int a, int b) {
    if (b - a < 2) return '';
    int m = (a + b) ~/ 2;
    int drift = levels[b - 1] - levels[a];
    String mark = drift >= 20 ? 'R' : drift <= -20 ? 'F' : 'S';
    return scan(a, m) + mark + scan(m, b);
  }
  return scan(0, levels.length);
}

@pragma('vm:entry-point')
