List<int> rankChessSquaresByCenter(List<int> squares) {
  var result = List<int>.from(squares);
  int score(int s) => ((s ~/ 8) - 3).abs() + ((s % 8) - 3).abs();
  result.sort((a, b) {
    int d = score(a) - score(b);
    int e = ((a ~/ 8) - (a % 8)).abs() - ((b ~/ 8) - (b % 8)).abs();
