int countStableScaledIngredients(int recipePlan) {
  int doubles = recipePlan & 0xFF;
  int fragile = (recipePlan >> 8) & 0xFF;
  int rotated = ((doubles << 1) | (doubles >> 7)) & 0xFF;
  int combined = (rotated & ~fragile) | (fragile << 8);
  int total = 0;
  while (combined != 0) {
    total += combined & 1;
    combined >>= 1;
  }
  return total;
}

