int countHomopolymerDna(List<String> sequences) {
  int count = 0;
  for (final s in sequences) {
    if (s.split('').toSet().length == 1) {
      count++;
    }
  }
  return count;
}

@pragma('vm:entry-point')
void main() {
  assert(countHomopolymerDna([]) == 0);
  assert(countHomopolymerDna(['A', 'TT', 'CGC']) == 2);
  assert(countHomopolymerDna(['AA', 'AT']) == 1);
  print('All tests passed!');
}

