  expect(candidate([]), 0);
  expect(candidate(['A']), 1);
  expect(candidate(['AC']), 0);
  expect(candidate(['AAA', 'TTT']), 2);
  expect(candidate(['ATCG']), 0);
  expect(candidate(['G', 'GG', 'GGG', 'GC']), 3);
  expect(candidate(['T', 'AT', 'TA']), 1);
  expect(candidate(['']), 0);
  expect(candidate(['A', 'C', 'G', 'T', 'AA', 'CC', 'GG', 'TT']), 8);
  expect(candidate(['AAAA', 'CCCC', 'GGGG', 'TTTT']), 4);
