num asciiRowSeamBits(List<int> rows) {
  var total = 0;
  for (final r in rows) {
    var seams = (r ^ ((r << 1) & 255)) & 255;
    total += seams.toRadixString(2).replaceAll('0', '').length;
  }
  return total;
}

