@pragma('vm:entry-point')
List<int> sortShelfNumbers(List<String> shelfCodes, bool alphabeticalFirst) {
  var indices = List.generate(shelfCodes.length, (i) => i);
  indices.sort((i, j) {
    if (alphabeticalFirst) {
      int cmp = shelfCodes[i][0].compareTo(shelfCodes[j][0]);
      if (cmp != 0) return cmp;
    }
    return int.parse(shelfCodes[i].substring(1)).compareTo(int.parse(shelfCodes[j].substring(1)));
  });
  return indices.map((i) => int.parse(shelfCodes[i].substring(1))).toList();
}

@pragma('vm:entry-point')
void main() {
  assert(sortShelfNumbers([], true).toString() == '[]');
  assert(sortShelfNumbers(['A5'], false).toString() == '[5]');
  assert(sortShelfNumbers(['C10', 'A2', 'B1'], true).toString() == '[2, 1, 10]');
  print('All tests passed!');
}

tests:
void main() {
  final candidate = sortShelfNumbers;

  expect(candidate([], true), []);
  expect(candidate([], false), []);
  expect(candidate(['A5'], false), [5]);
  expect(candidate(['A5'], true), [5]);
  expect(candidate(['B3', 'A1', 'B2'], true), [1, 2, 3]);
  expect(candidate(['B3', 'A1', 'B2'], false), [1, 2, 3]);
  expect(candidate(['C10', 'A2', 'B1'], true), [2, 1, 10]);
  expect(candidate(['C10', 'A2', 'B1'], false), [1, 2, 10]);
  expect(candidate(['A5', 'A3', 'A10'], true), [3, 5, 10]);
  expect(candidate(['A5', 'A3', 'A10'], false), [3, 5, 10]);
  expect(candidate(['B2', 'A1', 'A10', 'B5'], true), [1, 10, 2, 5]);
  expect(candidate(['B2', 'A1', 'A10', 'B5'], false), [1, 2, 5, 10]);
}

