List<String> collectNarrowDigitBarcodes(List<String> barcodes, int distinctLimit) {
  return barcodes
      .where((b) => b.split('').toSet().length <= distinctLimit)
      .map((b) => b.isEmpty ? 'empty' : '${b[0]}:${b[b.length - 1]}:${b.length}')
      .toSet()
      .toList();
