@pragma('vm:entry-point')
List<int> squareColorShiftSteps(List<String> squares) {
  var r = <int>[];
  bool c(String s) => ((s.codeUnitAt(0) + s.codeUnitAt(1)) & 1) == 0;
  void f(int i) {
    if (i >= squares.length - 1) return;
    if (c(squares[i]) != c(squares[i + 1])) r.add(i + 1);
    f(i + 1);
  }
  f(0);
  return r;
}

@pragma('vm:entry-point')
void main() {
  assert(squareColorShiftSteps(['a1']).toString() == '[]');
  assert(squareColorShiftSteps(['a1', 'a2', 'b2']).toString() == '[1, 2]');
  assert(squareColorShiftSteps(['h8', 'g7', 'f6']).length == 0);
