@pragma('vm:entry-point')
String formatSortedDeparturesByGroup(List<List<int>> trains) {
  List<List<int>> sorted = List.from(trains);
  sorted.sort((a, b) {
    if (a[1] != b[1]) return a[1].compareTo(b[1]);
    return a[0].compareTo(b[0]);
  });
  return sorted.map((t) => t[0].toString()).join(',');
}

