@pragma('vm:entry-point')
int performanceWeekdayForTicket(int ticketNumber) {
  int currentDay = 5; // Saturday
  int performed = 0;
  while (performed < ticketNumber) {
    if (currentDay != 6) performed++;
    currentDay = (currentDay + 1) % 7;
  }
  return (currentDay - 1 + 7) % 7;
}

