int countOddlyStackedItems(List<String> inventory) {
  var freq = <String, int>{};
  for (var item in inventory) freq.update(item, (v) => v + 1, ifAbsent: () => 1);
  return freq.values.where((v) => v % 2 == 1).length;
}

