@pragma('vm:entry-point')
List<int> sortLedgerEntriesByAbsoluteValue(List<int> amounts) {
  var sorted = List.of(amounts);
  sorted.sort((a, b) {
    int absDiff = a.abs() - b.abs();
    if (absDiff != 0) return absDiff;
    return a.compareTo(b);
  });
  return sorted;
}

@pragma('vm:entry-point')
void main() {
  assert(sortLedgerEntriesByAbsoluteValue([5, -5, 3, -3]).toString() == '[-3, 3, -5, 5]');
  assert(sortLedgerEntriesByAbsoluteValue([-2, -1, 0, 1, 2]).toString() == '[0, -1, 1, -2, 2]');
