String reorderLibraryShelfCodes(String shelfCodes) {
  if (shelfCodes.isEmpty) return '';
  var codes = shelfCodes.split('|');
  int digits(String s) => RegExp(r'\d').allMatches(s).length;
  codes.sort((a, b) {
    var diff = digits(a) - digits(b);
    return diff != 0 ? diff : (b.length != a.length ? b.length - a.length : a.compareTo(b));
  });
  return codes.join('|');
}

@pragma('vm:entry-point')
void main() {
  assert(reorderLibraryShelfCodes('') == '');
  assert(reorderLibraryShelfCodes('A1|LONG2|BB3') == 'LONG2|BB3|A1');
  assert(reorderLibraryShelfCodes('Z|AA|B1') == 'AA|Z|B1');
  print('All tests passed!');
}

tests:
void main() {
  final candidate = reorderLibraryShelfCodes;

  expect(candidate(''), '');
  expect(candidate('Q9'), 'Q9');
  expect(candidate('AB|A1|B22|C333'), 'AB|A1|B22|C333');
  expect(candidate('A1|LONG2|BB3'), 'LONG2|BB3|A1');
  expect(candidate('B7|A5|CC1'), 'CC1|A5|B7');
  expect(candidate('Z|AA|B1'), 'AA|Z|B1');
  expect(candidate('A12|B3|CDEF'), 'CDEF|B3|A12');
  expect(candidate('M|N|O1'), 'M|N|O1');
  expect(candidate('R2D2|A9|BOOK'), 'BOOK|A9|R2D2');
  expect(candidate('AA11|B222|C3|DD'), 'DD|C3|AA11|B222');
}

