@pragma('vm:entry-point')
bool isValidTrainDepartureSchedule(int scheduleMask) {
  int count = scheduleMask;
  count = (count & 0x5555555555555555) + ((count >> 1) & 0x5555555555555555);
  count = (count & 0x3333333333333333) + ((count >> 2) & 0x3333333333333333);
  count = (count & 0x0f0f0f0f0f0f0f0f) + ((count >> 4) & 0x0f0f0f0f0f0f0f0f);
  count = (count & 0x00ff00ff00ff00ff) + ((count >> 8) & 0x00ff00ff00ff00ff);
  count = (count & 0x0000ffff0000ffff) + ((count >> 16) & 0x0000ffff0000ffff);
  count = (count & 0x00000000ffffffff) + ((count >> 32) & 0x00000000ffffffff);
  return count != 0 && (count & (count - 1)) == 0 && (scheduleMask & (scheduleMask << 1)) == 0;
}

@pragma('vm:entry-point')
void main() {
  assert(isValidTrainDepartureSchedule(1) == true);
  assert(isValidTrainDepartureSchedule(3) == false);
  assert(isValidTrainDepartureSchedule(0) == false);
  print('All tests passed!');
}

