  expect(candidate(1), true);
  expect(candidate(2), true);
  expect(candidate(3), false);
  expect(candidate(4), true);
  expect(candidate(5), true);
  expect(candidate(0x14), true);
  expect(candidate(0x55), true);
  expect(candidate(1 << 59), true);
  expect(candidate((1 << 59) | 1), true);
  expect(candidate((1 << 59) | (1 << 58)), false);
