bool hasEnoughAfterDamagedDiscard(List<int> quantities) {
  int originalSum = quantities.fold(0, (sum, q) => sum + q);
  int remainingSum = quantities.fold(0, (sum, q) => sum + (q > 3 ? q : 0));
