int countDuplicateSquares(List<String> squares) {
  var freq = <String, int>{};
  for (var sq in squares) {
    freq.update(sq, (v) => v + 1, ifAbsent: () => 1);
  }
  return freq.values.where((v) => v > 1).length;
}

