@pragma('vm:entry-point')
List<int> groupByMorseDotCount(List<String> morseCodes) {
  var freq = <int, int>{};
  for (var code in morseCodes) {
    int dots = code.length - code.replaceAll('.', '').length;
    freq.update(dots, (v) => v + 1, ifAbsent: () => 1);
  }
  var keys = freq.keys.toList()..sort();
  return keys.map((k) => freq[k]!).toList();
}

