List<int> sortLogIndicesBySeverityAndTimestamp(List<String> logs) {
  var levels = {"DEBUG":0,"INFO":1,"WARN":2,"ERROR":3};
  List<int> indices = List.generate(logs.length, (i) => i);
  indices.sort((a,b){
    var pa = logs[a].split(' '), pb = logs[b].split(' ');
    int cmp = levels[pb[0]]!.compareTo(levels[pa[0]]!);
    if (cmp != 0) return cmp;
    return int.parse(pa[1]).compareTo(int.parse(pb[1]));
  });
  return indices;
}

