List<int> orderAuditLedgerEntries(List<int> entries, int auditFloor) {
  var out = List<int>.from(entries);
  out.sort((a, b) {
    var aa = a.abs() >= auditFloor, bb = b.abs() >= auditFloor;
    return aa == bb ? (a.abs() == b.abs() ? a - b : a.abs() - b.abs()) : (aa ? -1 : 1);
  });
  return out;
}

