@pragma('vm:entry-point')
List<String> evaluateScheduleBalance(List<int> schedules) {
  return schedules.map((s) {
    int c = s - ((s >> 1) & 0x55555555);
    c = (c & 0x33333333) + ((c >> 2) & 0x33333333);
    c = (c + (c >> 4)) & 0x0F0F0F0F;
    c = c + (c >> 8);
    c = c + (c >> 16);
    c &= 0x3F;
    return c == 12 ? "Balanced" : c > 12 ? "More On" : "More Off";
  }).toList();
}

@pragma('vm:entry-point')
void main() {
  assert(evaluateScheduleBalance([0x0FFF]).toString() == '["Balanced"]');
  assert(evaluateScheduleBalance([]).toString() == '[]');
  assert(evaluateScheduleBalance([0, 0xFFFFFF]).toString() == '["More Off", "More On"]');
  print('All tests passed!');
}

