  final candidate = sortPassWindowsByAverageDuration;

  expect(candidate([]), []);
  expect(candidate([7]), [7]);
  expect(candidate([3,3,3]), [3,3,3]);
  expect(candidate([1,2,3,4]), [2,1,3,4]);
  expect(candidate([5,1,9,3]), [3,1,5,9]);
  expect(candidate([10,10,5,15]), [5,10,10,15]);
