int countCentRoundingWays(List<int> data) {
  final target = data[0], floors = data.sublist(1);
  int count = 0;
  void dfs(int i, int s) {
    if (i == floors.length) { if (s == target) count++; return; }
    dfs(i + 1, s + floors[i]);
    dfs(i + 1, s + floors[i] + 1);
  }
  dfs(0, 0);
  return count;
}

