int caesarChessFileSum(String squares, int shift) {
  int sum = 0;
  for (int i = 0; i < squares.length; i += 2) {
    int fileIndex = squares.codeUnitAt(i) - 97;
    int newIndex = ((fileIndex + shift) % 8 + 8) % 8;
    sum += newIndex + 1;
  }
  return sum;
}

