  expect(candidate([5]), 'H');
  expect(candidate([1, 1]), 'W');
  expect(candidate([2, 4]), null);
  expect(candidate([2, 3, 4]), null);
  expect(candidate([4, 4, 5]), 'S>H');
  expect(candidate([5, 5, 0, 0]), 'H>W');
  expect(candidate([0, 2, 2, 5]), 'W>S>H');
  expect(candidate([0, 0, 3, 3, 0]), 'W>S>W');
}

