List<String> sortDnaByBaseCount(List<String> sequences, String base) {
  List<String> sorted = List.from(sequences);
  sorted.sort((a, b) {
    int countA = a.codeUnits.where((c) => c == base.codeUnitAt(0)).length;
    int countB = b.codeUnits.where((c) => c == base.codeUnitAt(0)).length;
    if (countA != countB) return countB - countA;
    return a.compareTo(b);
  });
  return sorted;
}

