String qrRingCenterGap(List<int> centers) {
  var l = 0, r = centers.length - 1;
  while (l <= r) {
    var m = (l + r) >> 1;
    if (centers[m] > 7 + m * 4) r = m - 1; else l = m + 1;
  }
  return 'A${7 + l * 4}';
}

