String summarizeInventory(List<String> items) {
  var counts = <String, int>{};
  for (var item in items) {
    counts.update(item, (v) => v + 1, ifAbsent: () => 1);
  }
  return counts.entries.map((e) => e.value == 1 ? e.key : '${e.key} (x${e.value})').join(', ');
}

