bool hasBalancedPassCoverage(List<List<int>> grid, int threshold) {
  if (grid.isEmpty) return false;
  int total = 0;
  for (final row in grid) {
    int rowSum = row.fold(0, (a, b) => a + b);
    if (rowSum == 0) return false;
    total += rowSum;
  }
  return total < threshold;
}

