List<double> decodeShelfChecksumBands(String code) {
  var r = <double>[];
  for (var i = 1; i < code.length; i += 2) {
    r.add(((code.codeUnitAt(i - 1) - 64) + code.codeUnitAt(i) - 48) / 2);
  }
  return r;
}

@pragma('vm:entry-point')
void main() {
  assert(decodeShelfChecksumBands('').length == 0);
  assert(decodeShelfChecksumBands('A0').toString() == '[0.5]');
  assert(decodeShelfChecksumBands('B3Z9').length == 2);
  print('All tests passed!');
}

tests:
