  final candidate = decodeShelfChecksumBands;

  expect(candidate(''), []);
  expect(candidate('A0'), [0.5]);
  expect(candidate('B3'), [2.5]);
  expect(candidate('C4D'), [3.5]);
  expect(candidate('A1B2'), [1.0, 2.0]);
  expect(candidate('M5'), [9.0]);
  expect(candidate('Z9'), [17.5]);
  expect(candidate('D0E1F2'), [2.0, 3.0, 4.0]);
  expect(candidate('Y8'), [16.5]);
  expect(candidate('H7A0'), [7.5, 0.5]);
}

