List<int> indicesOfLowGreenRows(List<List<int>> image) {
  var result = <int>[];
  for (var i = 0; i < image.length; i++) {
    double avgGreen = image[i].fold<int>(0, (sum, p) => sum + ((p >> 8) & 0xFF)) / image[i].length;
