String majorityVerdictForTally(List<int> votes) {
  int sum = 0, maxVotes = -1, maxIndex = -1;
  for (int i = 0; i < votes.length; i++) {
    sum += votes[i];
    if (votes[i] > maxVotes) { maxVotes = votes[i]; maxIndex = i; }
