bool hasThreeSeparatedDots(int symbols) {
  if (symbols <= 0) return false;
  var x = symbols;
  var dots = 0;
  while (x != 0) {
    dots++;
    x &= x - 1;
  }
  return dots == 3 && (symbols & (symbols << 1)) == 0;
}

