bool validateShippingPattern(String manifest, String pattern) {
  int pi = 0;
  for (int i = 0; i < manifest.length && pi < pattern.length; i++) {
    int c = manifest.codeUnitAt(i);
    if (c >= 65 && c <= 90) {
      if (c == pattern.codeUnitAt(pi)) {
        pi++;
      }
    }
  }
  return pi == pattern.length;
}

