@pragma('vm:entry-point')
int rgbPixelHarmonyMask(List<int> pixels) {
  var mask = 0;
  for (var p in pixels) {
    var r = (p >> 16) & 255, g = (p >> 8) & 255, b = p & 255;
    var d1 = (r - g).abs(), d2 = (g - b).abs();
    var bits = (r ^ g ^ b) & 15;
    if (d1 <= 8 && d2 <= 8) {
      mask = ((mask << 1) | (mask >> 15)) & 65535;
      mask ^= 1 << bits;
    } else {
      mask ^= ((bits << 1) | (bits >> 3)) & 31;
    }
  }
  return mask;
}

@pragma('vm:entry-point')
void main() {
  assert(rgbPixelHarmonyMask([]) == 0);
  assert(rgbPixelHarmonyMask([0x000000, 0x000000]) == 3);
  assert(rgbPixelHarmonyMask([0xFFFFFF, 0x000000]) == 0);
  print('All tests passed!');
}

