List<double> tideCrossingPair(List<double> readings) {
  int low = 0;
  int high = readings.length;
  while (low < high) {
    int mid = (low + high) >> 1;
    if (readings[mid] < 0.0) {
      low = mid + 1;
    } else {
      high = mid;
    }
  }
  if (low == 0 || low == readings.length) return [];
  return [readings[low - 1], readings[low]];
}

