int totalElevatorDistance(List<int> requests, int startFloor) {
  if (requests.isEmpty) return 0;
  int pickup = requests[0];
  int dropoff = requests[1];
  int tripDistance = (pickup - startFloor).abs() + (dropoff - pickup).abs();
  return tripDistance + totalElevatorDistance(requests.sublist(2), dropoff);
}

