int tournamentRounds(String bracket) {
  int depth = 0, maxDepth = 0;
  for (int i = 0; i < bracket.length; i++) {
    if (bracket[i] == '(') {
      if (++depth > maxDepth) maxDepth = depth;
    } else if (bracket[i] == ')') {
