int morseUndoPulseTotal(String signals) {
  var stack = <int>[];
  for (var c in signals.split('')) {
    if (c == '!') {
      if (stack.isNotEmpty) stack.removeLast();
    } else {
      stack.add(c == '.' ? 1 : 3);
