String electionClinchingDay(List<int> dailyVotes) {
  int total = dailyVotes.fold(0, (sum, v) => sum + v);
  int running = 0;
  for (int i = 0; i < dailyVotes.length; i++) {
    running += dailyVotes[i];
    if (running * 2 > total) return 'Day ${i + 1}';
  }
  return 'Never';
}

