String encodePlaylistCompact(String playlist) {
  var buf = StringBuffer(), c = 1;
  for (int i = 1; i <= playlist.length; i++) {
    if (i < playlist.length && playlist[i] == playlist[i-1]) { c++; }
    else {
      buf.write('${String.fromCharCode((playlist[i-1].codeUnitAt(0)-97+1)%26+97)}$c');
