int sumVipSeatPositions(String encodedSeats, int shift, String targetChar) {
  int sum = 0;
  for (int i = 0; i < encodedSeats.length; i++) {
    int c = encodedSeats.codeUnitAt(i);
    int decodedIndex = ((c - 65 - shift) % 26 + 26) % 26;
    if (String.fromCharCode(decodedIndex + 65) == targetChar) {
      sum += i + 1;
    }
  }
  return sum;
}

