bool verifyChargeChecksum(String rle, int checksum) {
  int sum = 0, num = 0;
  for (int i = 0; i < rle.length; i++) {
    int c = rle.codeUnitAt(i);
    if (c >= 48 && c <= 57) num = num * 10 + (c - 48);
    else { if (c == 67) sum += num; num = 0; }
  }
  return sum % 10 == checksum;
}

