bool canTileGenomeWithGates(String dna, int span) {
  var dp = List.filled(dna.length + 1, false);
  dp[0] = true;
  for (var i = 0; i + span <= dna.length; i++) {
    if (dp[i] && dna.substring(i, i + span).contains('G')) dp[i + span] = true;
