List<int> findLongestOpenSegment(List<int> cells) {
  int maxLen = 0, start = -1, curStart = 0, curLen = 0;
  for (int i = 0; i < cells.length; i++) {
    if (cells[i] > 0) {
      curLen++;
      if (curLen > maxLen) { maxLen = curLen; start = curStart; }
    } else { curStart = i + 1; curLen = 0; }
  }
  return [start, maxLen];
}

