List<num> morseShiftDigest(String code, int shift) {
  var sum = 0, dots = 0;
  for (var c in code.split('')) {
    var v = c == '.' ? 1 : c == '-' ? 3 : -1;
    sum += v + shift;
    dots += c == '.' ? 1 : 0;
  }
  return [sum, dots];
}

