bool isTemperatureInSchedule(List<int> data) {
  int target = data[0];
  int lo = 1, hi = data.length - 1;
  while (lo <= hi) {
    int mid = (lo + hi) ~/ 2;
    if (data[mid] == target) return true;
    if (data[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return false;
}

@pragma('vm:entry-point')
