String firstLongEnoughPassword(List<String> sortedPasswords, int minLength) {
  int left = 0, right = sortedPasswords.length - 1, result = -1;
  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    if (sortedPasswords[mid].length >= minLength) { result = mid; right = mid - 1; } else { left = mid + 1; }
  }
  return result == -1 ? "none" : sortedPasswords[result];
}

