bool hasAtLeastKHitSongs(List<int> playlistData) {
  int k = playlistData[0], threshold = playlistData[1];
  List<int> counts = playlistData.sublist(2);
  int left = 0, right = counts.length - 1;
  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    if (counts[mid] >= threshold) left = mid + 1;
    else right = mid - 1;
  }
  return left >= k;
}

