List<int> countTrainsPerIntervalBucket(List<int> departureMinutes, int intervalMinutes) {
  if (departureMinutes.isEmpty) return [];
  Map<int, int> bucketCounts = {};
  for (int t in departureMinutes) {
    int bucket = t ~/ intervalMinutes;
    bucketCounts[bucket] = (bucketCounts[bucket] ?? 0) + 1;
  }
  List<int> counts = [];
  List<int> sortedBuckets = bucketCounts.keys.toList()..sort();
  for (int b in sortedBuckets) {
    counts.add(bucketCounts[b]!);
  }
  return counts;
}

