int calculateRemainingQueueSum(List<String> logs, List<int> initial) {
  var queue = List<int>.from(initial);
  for (final log in logs) {
    if (log.startsWith('ENQUEUE ')) {
      queue.add(int.parse(log.substring(8)));
    } else if (log.startsWith('DEQUEUE')) {
      if (queue.isNotEmpty) queue.removeAt(0);
    }
  }
  return queue.fold(0, (a, b) => a + b);
}

