int dnaRunChecksum(String sequence) {
  const baseVal = {'A': 1, 'C': 2, 'G': 3, 'T': 4};
  var sum = 0, count = 0, prev = '';
  for (var i = 0; i < sequence.length; i++) {
    if (sequence[i] == prev) {
      count++;
    } else {
      sum += count > 0 ? baseVal[prev]! * count : 0;
      prev = sequence[i];
      count = 1;
    }
  }
  sum += count > 0 ? baseVal[prev]! * count : 0;
  return sum;
}

