  assert(longestBalancedChessWindow(['a1']).toString() == '[0, 1]');
  assert(longestBalancedChessWindow(['a1', 'b1', 'c1']).toString() == '[0, 3]');
  assert(longestBalancedChessWindow(['a1', 'c1', 'e1', 'b1']).toString() == '[2, 2]');
  print('All tests passed!');
