  expect(candidate('FAIL@500>disk\nFAIL@12>panic'), 'ALARM:0/0/2/0');
  expect(candidate('BAD@1>up'), 'CLEAR:0/0/0/1');
  expect(candidate('OK@1a>up'), 'CLEAR:0/0/0/1');
  expect(candidate('OK@2>Up'), 'CLEAR:0/0/0/1');
