List<int> scanSpellEditTokens(String log) {
  var counts = [0, 0, 0, 0];
  String pending = '';
  for (var i = 0; i < log.length; i++) {
    var c = log[i];
    if (c == '+' || c == '-' || c == '~') {
      if (pending.isNotEmpty) counts[3]++;
      pending = c;
    } else if (pending.isNotEmpty && c.codeUnitAt(0) >= 97 && c.codeUnitAt(0) <= 122) {
      counts[pending == '+' ? 0 : pending == '-' ? 1 : 2]++;
      pending = '';
    }
  }
  if (pending.isNotEmpty) counts[3]++;
  return counts;
}

