bool hasPrimeGcd(List<int> voteCounts) {
  int gcd(int a, int b) => b == 0 ? a : gcd(b, a % b);
  int g = voteCounts.fold(0, gcd);
  for (int i = 2; i * i <= g; i++) {
    if (g % i == 0) return false;
  }
  return g > 1;
}

