void main() {
  assert(maximizeManifestTransferCredits([]) == 0);
  assert(maximizeManifestTransferCredits(['12', '34']) == 6);
  assert(maximizeManifestTransferCredits(['1#2', '345', '67#']) == 14);
  print('All tests passed!');
}

