  assert(satelliteRelayCellScore([], 3) == 0);
  assert(satelliteRelayCellScore([0, 0, 2, 2, 1, 1, 3, 3], 3) == 2);
  assert(satelliteRelayCellScore([0, 0, 1, 1, 1, 1, 2, 2], 2) == 1);
  print('All tests passed!');
