  expect(candidate([4, 1], 3).toString(), '[[4, 8, 12], [3, 5, 5]]');
  expect(candidate([5, 4], 1).toString(), '[[3], [4]]');
  expect(candidate([-1], 3).toString(), '[[0, -2, -2]]');
  expect(candidate([2, 5], 0).toString(), '[[], []]');
}

