  final candidate = summarizePacketQueueBands;

  expect(candidate([]), 'idle');
  expect(candidate([-1, -5]), 'blocked');
  expect(candidate([0]), 'z1|sync');
  expect(candidate([5]), 's1');
  expect(candidate([4, 9, 14]), 's1|s1|s1');
  expect(candidate([64, 64, 12, 513]), 'm2|l1|s1|drift');
  expect(candidate([7, 2, 17, 22]), 's1|s1|s1|s1');
  expect(candidate([63, 64, 512, 513]), 'm1|s1|l1|m1');
  expect(candidate([1, 1, 1, 1, 1, 1, 1]), 's7|sync');
