int sumTideDifferencesWithinDistance(List<List<int>> readings, int maxDistance) {
  int total = 0;
  for (int i = 0; i < readings.length - 1; i++) {
    int x1 = readings[i][0], y1 = readings[i][1], h1 = readings[i][2];
    int x2 = readings[i+1][0], y2 = readings[i+1][1], h2 = readings[i+1][2];
    if ((x1 - x2).abs() + (y1 - y2).abs() <= maxDistance)
      total += (h1 - h2).abs();
  }
  return total;
}

