List<int> decodeRoundedCentTape(String s) {
  var out = <int>[];
  var value = 0;
  for (var i = 0; i < s.length; i++) {
    var c = s.codeUnitAt(i);
    if (c >= 48 && c <= 57) {
      value = value * 10 + c - 48;
    } else if (c == 117 || c == 100) {
      var rem = value % 5;
      out.add(c == 117 ? value + (5 - rem) % 5 : value - rem);
      value = 0;
    }
  }
  return out;
}

