String deckPacketHex(List<int> stacks) {
  var g = 0;
  for (var v in stacks) {
    v = v.abs();
    if (v == 0) continue;
    while (g != 0 && v != 0) {
      var t = g % v;
      g = v;
      v = t;
    }
    if (g == 0) g = v;
  }
  return g.toRadixString(16).toUpperCase();
}

