bool isMazeRleBalanced(String encoded) {
  int wallCount = 0, passageCount = 0;
  for (int i = 0; i < encoded.length; i += 2) {
    String type = encoded[i];
    int count = int.parse(encoded[i + 1]);
    if (type == 'W') {
