int pendingSpellEditDrift(List<String> edits) {
  var stack = <int>[];
  for (var e in edits) {
    if (e == 'undo') {
      if (stack.isNotEmpty) stack.removeLast();
    } else {
      stack.add(e.startsWith('!') ? 1 - e.length : e.length);
    }
  }
  var total = 0;
  for (var v in stack) total += v;
  return total < 0 ? -total : total;
}

